diagnosis_db = LoadDB('diagnosis')
diagnosis_list = GetValue(diagnosis_db, 'diagnosisstring, list')
diagnosis_frequency = {}
for diagnosis in diagnosis_list:
    if diagnosis not in diagnosis_frequency:
        diagnosis_frequency[diagnosis] = 0
    diagnosis_frequency[diagnosis] += 1
top_five_diagnoses = sorted(diagnosis_frequency.items(), key=lambda x: x[1], reverse=True)[:5]
answer = [diagnosis[0] for diagnosis in top_five_diagnoses]

date = Calendar('-2103 year')
medication_db = LoadDB('medication')
filtered_medication_db = FilterDB(medication_db, 'startyear>{}'.format(date))
drug_frequency = {}
for drug in GetValue(filtered_medication_db, 'drugname, list'):
    if drug not in drug_frequency:
        drug_frequency[drug] = 0
    drug_frequency[drug] += 1
answer = sorted(drug_frequency.items(), key=lambda x: x[1], reverse=True)[:3]
